// Plantilla del grupo web: valor de TypeScript con la forma de una plantilla de CloudFormation.
export const template = {
  AWSTemplateFormatVersion: "2010-09-09",
  Description: "Grupo web con capacidad entre 2 y 6 instancias",
  Parameters: {
    ImagenId: { Type: "String" },
    Subredes: { Type: "CommaDelimitedList" },
  },
  Resources: {
    PlantillaWeb: {
      Type: "AWS::EC2::LaunchTemplate",
      Properties: {
        LaunchTemplateData: { ImageId: { Ref: "ImagenId" }, InstanceType: "t3.micro" },
