spec.code:
const predefinidas = ["ASGAverageCPUUtilization", "ASGAverageCPUUtilizationHighResolution", "ASGAverageNetworkIn", "ASGAverageNetworkOut", "ALBRequestCountPerTarget"];
const metrica = template.Resources.PoliticaSolicitudes.Properties.TargetTrackingConfiguration.PredefinedMetricSpecification.PredefinedMetricType;
assert.ok(predefinidas.includes(metrica), "La métrica «" + metrica + "» no es una métrica predefinida de seguimiento de objetivo");
assert.strictEqual(metrica, "ALBRequestCountPerTarget", "Para escalar por solicitudes por instancia usa ALBRequestCountPerTarget");

const especificacion = template.Resources.PoliticaSolicitudes.Properties.TargetTrackingConfiguration.PredefinedMetricSpecification;
assert.deepStrictEqual(especificacion.ResourceLabel, { Ref: "EtiquetaGrupoDestino" });
assert.ok(Object.keys(template.Parameters).includes("EtiquetaGrupoDestino"), "Falta el parámetro EtiquetaGrupoDestino");

const propiedades = template.Resources.GrupoWeb.Properties;
assert.strictEqual(propiedades.MinSize, "2");
assert.strictEqual(propiedades.MaxSize, "6");
assert.strictEqual(propiedades.DesiredCapacity, "2");
const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("PlantillaWeb") < orden.indexOf("GrupoWeb"), "PlantillaWeb debe crearse antes que GrupoWeb");
assert.ok(orden.indexOf("GrupoWeb") < orden.indexOf("PoliticaSolicitudes"), "GrupoWeb debe crearse antes que PoliticaSolicitudes");

