spec.code:
const tipos = Object.values(template.Resources).map((recurso) => recurso.Type);
assert.ok(tipos.includes("AWS::EC2::LaunchTemplate"), "Falta un recurso AWS::EC2::LaunchTemplate");
assert.ok(tipos.includes("AWS::AutoScaling::AutoScalingGroup"), "Falta un recurso AWS::AutoScaling::AutoScalingGroup");
assert.ok(aws.cfn.dependencyOrder(template) !== null, "La plantilla tiene una dependencia circular");

const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("PlantillaWeb") < orden.indexOf("GrupoWeb"), "PlantillaWeb debe crearse antes que GrupoWeb");
assert.ok(orden.indexOf("GrupoWeb") < orden.indexOf("PoliticaCpu"), "GrupoWeb debe crearse antes que PoliticaCpu");

const propiedades = template.Resources.GrupoWeb.Properties;
const minimo = Number(propiedades.MinSize);
const maximo = Number(propiedades.MaxSize);
const deseada = Number(propiedades.DesiredCapacity);
assert.strictEqual(minimo, 2);
assert.strictEqual(maximo, 6);
assert.ok(minimo <= deseada && deseada <= maximo, "La capacidad deseada debe estar entre el mínimo y el máximo");

const politica = template.Resources.PoliticaCpu;
assert.strictEqual(politica.Type, "AWS::AutoScaling::ScalingPolicy");
assert.deepStrictEqual(politica.Properties.AutoScalingGroupName, { Ref: "GrupoWeb" });
assert.strictEqual(politica.Properties.PolicyType, "TargetTrackingScaling");
const configuracion = politica.Properties.TargetTrackingConfiguration;
assert.strictEqual(configuracion.PredefinedMetricSpecification.PredefinedMetricType, "ASGAverageCPUUtilization");
assert.strictEqual(configuracion.TargetValue, 50);

